DROP TABLE IF EXISTS `logs_seguranca`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `logs_seguranca` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int DEFAULT NULL COMMENT 'ID do usuário (null se login falhou)',
  `tipo_evento` enum('login_sucesso','login_falha','logout','token_refresh','senha_alterada','bloqueio','desbloqueio') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `detalhes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Informações adicionais em JSON',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_usuario` (`usuario_id`),
  KEY `idx_tipo` (`tipo_evento`),
  KEY `idx_data` (`created_at`),
  CONSTRAINT `logs_seguranca_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=245 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Log de eventos de segurança';
/*!40101 SET character_set_client = @saved_cs_client */;

